{"command": "E=<email:d29caa5c>
{ echo "hash,date,type,files_changed,lines_added,lines_deleted,subject"
git log --author=$E --format='@@%h|%ad|%p|%s' --date=short --numstat | awk -F'|' '
function flush(){ if(h!="") printf "%s,%s,%s,%d,%d,%d,\"%s\"\n",h,d,t,f,a,r,s }
/^@@/{flush(); h=substr($1,3); d=$2; n=split($3,p," "); t=(n>1)?"merge":"authored"; s=$4; gsub(/"/,"\"\"",s); f=0;a=0;r=0; next}
NF&&$0!~/^@@/{split($0,x,"\t"); f++; if(x[1]!="-")a+=x[1]; if(x[2]!="-")r+=x[2]}
END{flush()}'; } > contributions.csv
wc -l contributions.csv; head -4 contributions.csv
git log --author=$E --no-merges --format=%h | wc -l; git log --format='%an' | sort -u | wc -l
git log --show-signature -1 --author=$E 2>&1 | head -3; git rev-parse HEAD"}
